35	#elif defined(PTO_NPU_ARCH_A2A3)
36	PTO_INTERNAL void SYNCALL_SOFT_DCCI(__gm__ void* ptr)
37	{
38	    __asm__ __volatile__("");
39	    dcci(ptr, cache_line_t::SINGLE_CACHE_LINE);
40	    __asm__ __volatile__("");
41	}
