43	PTO_INTERNAL int32_t SYNCALL_SOFT_ATOMIC_LOAD(__gm__ int32_t* counter)
44	{
45	    return static_cast<int32_t>(ld_dev(reinterpret_cast<__gm__ uint32_t*>(counter), 0));
46	}
47	
48	// Hardware scalar atomic-add of 1; the dcci write-back is the atomic publication point
49	// (same pattern as comm TNOTIFY AtomicAdd). set_st_atomic_cfg configures the scalar
50	// st_atomic path only — a separate SPR from the DMA/fixpipe atomic mode that
51	// set_atomic_none() clears — so no reset belongs here.
52	PTO_INTERNAL void SYNCALL_SOFT_ATOMIC_ADD(__gm__ int32_t* counter)
53	{
54	    set_st_atomic_cfg(ATOMIC_S32, ATOMIC_SUM);
55	    SYNCALL_SOFT_DCCI(static_cast<__gm__ void*>(counter));
56	    st_atomic<int32_t>(1, counter);
57	    SYNCALL_SOFT_DCCI(static_cast<__gm__ void*>(counter));
58	    dsb(DSB_DDR);
59	}
