97	{
98	    int32_t pollCount = 0;
99	    while (SYNCALL_SOFT_ATOMIC_LOAD(counter) < target) {
100	        if ((++pollCount % SYNCALL_SOFT_BACKOFF_THRESHOLD) == 0) {
101	            pipe_barrier(PIPE_ALL);
102	        }
103	        if (pollCount >= SYNCALL_SOFT_MAX_POLL_ITERATIONS) {
104	            PTO_CPU_ASSERT(false, "SYNCALL soft barrier timeout - possible deadlock");
