16	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_>
17	AICORE void runTAdd(__gm__ T __out__* out, __gm__ T __in__* src0, __gm__ T __in__* src1)
18	{
19	    using DynShapeDim5 = Shape<1, 1, 1, kGRows_, kGCols_>;
20	    using DynStridDim5 = Stride<1, 1, 1, kGCols_, 1>;
21	    using GlobalData = GlobalTensor<T, DynShapeDim5, DynStridDim5>;
22	    using TileData = Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1>;
23	    TileData src0Tile(kTRows_, kTCols_);
24	    TileData src1Tile(kTRows_, kTCols_);
25	    TileData dstTile(kTRows_, kTCols_);
26	    TASSIGN(src0Tile, 0x0);
27	    TASSIGN(src1Tile, 0x4000);
28	    TASSIGN(dstTile, 0x8000);
29	
30	    GlobalData src0Global(src0);
31	    GlobalData src1Global(src1);
32	    GlobalData dstGlobal(out);
33	
34	    TLOAD(src0Tile, src0Global);
35	    TLOAD(src1Tile, src1Global);
36	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
37	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
38	    TADD(dstTile, src0Tile, src1Tile);
39	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
40	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
41	    TSTORE(dstGlobal, dstTile);
42	    out = dstGlobal.data();
43	}
44	
45	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_>
46	void LaunchTAdd(T* out, T* src0, T* src1, void* stream)
47	{
48	    if constexpr (std::is_same_v<T, aclFloat16>)
49	        runTAdd<half, kGRows_, kGCols_, kTRows_, kTCols_>((half*)(out), (half*)(src0), (half*)(src1));
50	    else
51	        runTAdd<T, kGRows_, kGCols_, kTRows_, kTCols_>(out, src0, src1);
52	}
