54	template void LaunchTAdd<float, 64, 64, 64, 64>(float* out, float* src0, float* src1, void* stream);
55	template void LaunchTAdd<int32_t, 64, 64, 64, 64>(int32_t* out, int32_t* src0, int32_t* src1, void* stream);
56	template void LaunchTAdd<aclFloat16, 16, 256, 16, 256>(
57	    aclFloat16* out, aclFloat16* src0, aclFloat16* src1, void* stream);
58	template void LaunchTAdd<int16_t, 64, 64, 64, 64>(int16_t* out, int16_t* src0, int16_t* src1, void* stream);
